ALTER TABLE "Quote" ADD COLUMN "number" TEXT NOT NULL DEFAULT '', ADD COLUMN "date" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN "validUntil" TIMESTAMP(3), ADD COLUMN "tax" DECIMAL(14,2) NOT NULL DEFAULT 0, ADD COLUMN "notes" TEXT NOT NULL DEFAULT '', ADD COLUMN "lines" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "requestKey" TEXT;
UPDATE "Quote" SET "date" = "createdAt";
CREATE UNIQUE INDEX "Quote_requestKey_key" ON "Quote"("requestKey");
